// Kitchen is an instance of a component of the WIT world kitchen.
type Kitchen struct{ inst *component.Instance }

// Instantiate instantiates a component of the world kitchen, with imports implementing
// its imports. opts are passed on to component.Instantiate, for what the
// bindings leave to the host, such as WASI.
func Instantiate(ctx context.Context, r wazy.Runtime, wasm []byte, imports Imports, opts ...component.Option) (*Kitchen, error) {
	var o []component.Option
	if imports.Types == nil {
		return nil, fmt.Errorf("kitchen: imports.Types is nil")
	}
	o = append(o, optionsTypes(imports.Types)...)
	if imports.Host == nil {
		return nil, fmt.Errorf("kitchen: imports.Host is nil")
	}
	o = append(o, optionsHost(imports.Host)...)
	inst, err := component.Instantiate(ctx, r, wasm, append(o, opts...)...)
	if err != nil {
		return nil, err
	}
	return &Kitchen{inst: inst}, nil
}

